import { parseArgs } from './lib/argparse.mjs';
import { decode } from './lib/decoder.mjs';
import { pyRepr } from './lib/pyrepr.mjs';

const prog = process.argv[1].split('/').pop();

const args = parseArgs(process.argv.slice(2), prog);

try {
  const result = decode(args.a);
  console.log(pyRepr(result));
} catch (e) {
  process.stderr.write(e.message + '\n');
  process.exit(1);
}

