// Format a decoded bencode value (tagged plain object) the way Python's
// print() would render the corresponding object.

function bytesRepr(data) {
  const quote = data.includes("'") && !data.includes('"') ? '"' : "'";
  let out = 'b' + quote;
  for (let i = 0; i < data.length; i++) {
    const ch = data[i];
    const code = data.charCodeAt(i);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (code < 32 || code === 127) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  return out + quote;
}

export function pyRepr(value) {
  switch (value.kind) {
    case 'int':
      return value.value.toString();
    case 'bytes':
      return bytesRepr(value.data);
    case 'list':
      return '[' + value.items.map(pyRepr).join(', ') + ']';
    case 'dict':
      return (
        '{' +
        value.entries
          .map(([k, v]) => pyRepr(k) + ': ' + pyRepr(v))
          .join(', ') +
        '}'
      );
    default:
      throw new Error('pyRepr: unknown value kind: ' + value.kind);
  }
}

