// Minimal re-implementation of Python argparse for a single required
// option `--a A` (type str) plus the automatic -h/--help.

function usage(prog) {
  return `usage: ${prog} [-h] --a A\n`;
}

function error(prog, message) {
  process.stderr.write(usage(prog) + `${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog) {
  process.stdout.write(
    usage(prog) +
      '\noptions:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A\n'
  );
  process.exit(0);
}

// argparse's negative-number rule: a token that looks like an option is
// still accepted as a value if it matches a negative number pattern.
function looksLikeNegativeNumber(token) {
  return /^-\d+$/.test(token) || /^-\d*\.\d+$/.test(token);
}

export function parseArgs(argv, prog) {
  let a;
  const leftovers = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === '-h' || token === '--help') {
      printHelp(prog);
    } else if (token === '--a') {
      const next = argv[i + 1];
      if (
        next === undefined ||
        (next.startsWith('-') && next.length > 1 && !looksLikeNegativeNumber(next))
      ) {
        error(prog, 'argument --a: expected one argument');
      }
      a = next;
      i++;
    } else if (token.startsWith('--a=')) {
      a = token.slice('--a='.length);
    } else {
      leftovers.push(token);
    }
  }

  if (a === undefined) {
    error(prog, 'the following arguments are required: --a');
  }
  if (leftovers.length > 0) {
    error(prog, `unrecognized arguments: ${leftovers.join(' ')}`);
  }
  return { a };
}

