// Bencode decoder replicating the behavior of the PyPI `bencoder` package.
// Input is a plain JS string (guaranteed ASCII); output uses the shared
// tagged-value contract:
//   bytes -> { kind: 'bytes', data: string }
//   int   -> { kind: 'int', value: BigInt }
//   list  -> { kind: 'list', items: [value, ...] }
//   dict  -> { kind: 'dict', entries: [[keyValue, valValue], ...] }

export function decode(s) {
  const [value, pos] = parseValue(s, 0);
  if (pos !== s.length) {
    throw new Error('TypeError: Malformed input.');
  }
  return value;
}

function parseValue(s, pos) {
  if (pos >= s.length) {
    throw new Error('IndexError: index out of range');
  }
  const ch = s[pos];

  if (ch === 'i') {
    const m = /^i(-?\d+)e/.exec(s.slice(pos));
    if (m === null) {
      throw new Error("AttributeError: 'NoneType' object has no attribute 'group'");
    }
    return [{ kind: 'int', value: BigInt(m[1]) }, pos + m[0].length];
  }

  if (ch >= '0' && ch <= '9') {
    const m = /^(\d+):/.exec(s.slice(pos));
    if (m === null) {
      throw new Error("AttributeError: 'NoneType' object has no attribute 'group'");
    }
    const start = pos + m[0].length;
    const n = parseInt(m[1], 10);
    // Python slice semantics: fewer than n remaining chars is not an error.
    const data = s.slice(start, start + n);
    return [{ kind: 'bytes', data }, start + data.length];
  }

  if (ch === 'l') {
    pos += 1;
    const items = [];
    for (;;) {
      if (pos >= s.length) {
        throw new Error('IndexError: index out of range');
      }
      if (s[pos] === 'e') {
        return [{ kind: 'list', items }, pos + 1];
      }
      const [v, next] = parseValue(s, pos);
      items.push(v);
      pos = next;
    }
  }

  if (ch === 'd') {
    pos += 1;
    const entries = [];
    for (;;) {
      if (pos >= s.length) {
        throw new Error('IndexError: index out of range');
      }
      if (s[pos] === 'e') {
        return [{ kind: 'dict', entries }, pos + 1];
      }
      const [k, afterKey] = parseValue(s, pos);
      const [v, afterVal] = parseValue(s, afterKey);
      entries.push([k, v]);
      pos = afterVal;
    }
  }

  throw new Error('AssertionError');
}

